package com.bank.ccr.model;
import jakarta.persistence.*; import java.math.BigDecimal;
@Entity public class CollateralPosition { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private String counterpartyId; private String nettingSetId; private String collateralType; private String currency; private BigDecimal marketValue; private BigDecimal haircutPct; protected CollateralPosition(){} public CollateralPosition(String c,String n,String t,String cur,BigDecimal v,BigDecimal h){counterpartyId=c;nettingSetId=n;collateralType=t;currency=cur;marketValue=v;haircutPct=h;} public Long getId(){return id;} public String getCounterpartyId(){return counterpartyId;} public String getNettingSetId(){return nettingSetId;} public String getCollateralType(){return collateralType;} public String getCurrency(){return currency;} public BigDecimal getMarketValue(){return marketValue;} public BigDecimal getHaircutPct(){return haircutPct;} }
